	private abstract class AbstractMember {
		private string memberName;
		private DataType dataType;
		private bool isFlexibleArray;
		private ClassFieldAttributes attributes;
		private string comment;

		private AbstractMember(string name, DataType dataType, bool isFlexibleArray,
				ClassFieldAttributes attributes) : this(name, dataType, isFlexibleArray, attributes, null)
    {
		}

		private AbstractMember(string name, DataType dataType, bool isFlexibleArray,
				ClassFieldAttributes attributes, string comment) {
			this.memberName = name;
			this.dataType = dataType;
			this.isFlexibleArray = isFlexibleArray;
			this.attributes = attributes;
			this.comment = comment;
		}

		/* @Override */
		public string toString() {
			StringBuilder builder = new StringBuilder();
			builder.append(dataType);
			if (builder.length() > 0 && memberName.length() > 0) {
				builder.append(' ');
			}
			builder.append(memberName);
			return builder.toString();
		}

		string getName() {
			return memberName;
		}

		DataType getDataType() {
			return dataType;
		}

		bool isFlexibleArray() {
			return isFlexibleArray;
		}

		ClassFieldAttributes getAttributes() {
			return attributes;
		}

		void setComment(string comment) {
			this.comment = comment;
		}

		string getComment() {
			return comment;
		}
	}

	private class StaticMember : AbstractMember {
		private StaticMember(string name, DataType dataType, ClassFieldAttributes attributes) : base(name, dataType, false, attributes)
    {
		}

		/* @Override */
		public string toString() {
			StringBuilder builder = new StringBuilder();
			builder.append(base.toString());
			if (builder.length() > 0) {
				builder.insert(0, "static ");
			}
			return builder.toString();
		}
	}

	private class Member : AbstractMember {
		private int offset;

		private Member(string name, DataType dataType, bool isFlexibleArray,
				ClassFieldAttributes attributes, int offset) : this(name, dataType, isFlexibleArray, attributes, offset, null)
    {
		}

		private Member(string name, DataType dataType, bool isFlexibleArray,
				ClassFieldAttributes attributes, int offset, string comment) : base(name, dataType, isFlexibleArray, attributes, comment)
    {
			this.offset = offset;
		}

		int getOffset() {
			return offset;
		}

	}

